(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["he"] = {"ui":{"skip":"דילוג לתוכן","back":"→ חזרה ל-AI-gile","lang.button":"שפה: {name}","lang.dialog":"בחרו שפה","lang.search":"חיפוש שפות","lang.none":"אין שפה מתאימה","lang.notYet":"{name} עדיין לא תורגמה","theme.aria":"מעבר בין ערכת נושא בהירה לכהה","theme.toLight":"מעבר לערכת נושא בהירה","theme.toDark":"מעבר לערכת נושא כהה","index.title":"AI-gile: צוות הפיתוח של ה-AI שלכם, בלוח אחד","index.description":"AI-gile הוא לוח קנבן לצוותי קוד של AI. הם עובדים בזמן שאתם ישנים; אתם מקבלים ערימה קצרה אחת של דברים להחליט עליהם, לבדוק ולאשר.","hero.logoAlt":"סמל הלוח של AI-gile","hero.h1.html":"צוות הפיתוח של ה-AI שלכם, בלוח&nbsp;אחד.","hero.alpha":"🐣 פרה-אלפא סגורה","hero.alphaTitle":"מוקדם ולא גמור: תודה שאתם מנסים!","hero.lede":"הם בונים בזמן שאתם ישנים. אתם מתעוררים אל ערימה קצרה אחת: כמה שאלות, כמה דברים לבדיקה, יהלום סגול או שניים. לוחצים, מאשרים, וחוזרים לקפה.","dl.windows":"אפליקציה ל-Windows","dl.browser":"להריץ בדפדפן","dl.soon":"בקרוב","dl.notify":"🔔 תגידו לי כשזה נפתח","dl.notifySmall":"אלפא או בטא","hero.secondary":"זריז (Agile), אבל הצוות לא צריך קפה של סטנד-אפ. (הם עושים סטנד-אפ בכל זאת.)","pitch.h2":"AI-gile בכמה מילים שתרצו","pitch.lede":"בחרו אורך, ממילה אחת ועד 144. לכל אורך יש תיאור משלו, שנכתב במיוחד לגודל הזה. גררו את המחוון או השתמשו בחצים.","pitch.rangeLabel":"אורך במילים","pitch.dice":"🎲 גרסה אחרת","pitch.words.one":"מילה {n}","pitch.words.two":"{n} מילים","pitch.words.other":"{n} מילים","pitch.letters.one":"אות {n}","pitch.letters.two":"{n} אותיות","pitch.letters.other":"{n} אותיות","pitch.chars.one":"תו {n}","pitch.chars.two":"{n} תווים","pitch.chars.other":"{n} תווים","count.line.html.one":"כרטיס {n} על הלוח כרגע","count.line.html.two":"{n} כרטיסים על הלוח כרגע","count.line.html.other":"{n} כרטיסים על הלוח כרגע","features.aria":"מה זה עושה","f.pile.h":"ערימה אחת בשבילכם","f.pile.html":"<b>בשבילכם</b> מחזיק את כל מה שמחכה לכם, מכל הפרויקטים: שאלות, דברים לבדיקה, משימות שרק בן אדם יכול לעשות. התור שלכם אומר מה הבא וכמה זמן זה לוקח.","f.sleep.h":"צוותים שעובדים בזמן שאתם ישנים","f.sleep.p":"לכל פרויקט יש Lead וצוות של סוכני AI. כתבו תגובה על כרטיס והצוות מתעורר, עושה את העבודה, ומחזיר אותה עם צעדים שגם בן אדם עייף יכול לעקוב אחריהם.","f.tester.h":"בודק AI בודק קודם","f.tester.p":"לפני שמשהו מגיע אליכם, בודק עוקב אחר הצעדים בעותק של האפליקציה ומראה מה ראה, עם צילום מסך. דפדפו בכרטיסים שעברו ואשרו בלחיצה.","f.proof.h":"הוכחות, לא הבטחות","f.proof.p":"כל מסירה מראה מה השתנה: הקבצים, ה-diff, צילומי המסך. אין צורך לפתוח כל אפליקציה כדי לדעת אם זה גמור.","f.chat.h":"שיחה עם ה-Lead שלכם","f.chat.p":"סרגל צד בסגנון Discord: סמל אחד לכל פרויקט, יהלומים סגולים למה שצריך אתכם. שלחו ל-Lead רעיון; הוא הופך אותו לכרטיסים ולתוכנית, עם כפתור ✅ Go.","f.tidy.h":"מסדר את עצמו","f.tidy.p":"כרטיסים קשורים מתמזגים לאחד, כותרות מבולבלות מתוקנות, ובדיקת טוקנים שומרת על קוד רזה. פחות דברים לעבור ביניהם, פחות לחשוב.","f.private.h":"שלכם, על המחשב שלכם","f.private.li1":"הלוח רץ על המחשב שלכם ועונה רק לכם.","f.private.li2":"הודעות פרטיות בין אנשים מוצפנות מקצה לקצה.","f.private.li3":"בלי חשבונות, בלי עוקבים, בלי עוגיות.","f.lang.h":"בשפה שלכם","f.lang.p":"יותר מ-120 שפות, מהולנדית, וולשית ויפנית ועד שפת פיראטים, יודה וקלינגונית, עם מעבר מהיר חזרה לאנגלית למילות המפתחים.","tl.aria":"ציר זמן מהשיחה הראשונה ועד מפת הדרכים","tl.h2":"מהשיחה הראשונה ועד מה שבא אחר כך","tl.lede":"תאריכים ושעות אמיתיים, באזור הזמן שלכם. אחרי היום זו תוכנית, בלי תאריכים מובטחים.","tl.today":"היום","tl.planned":"מתוכנן","tl.cards.one":"כרטיס {n}","tl.cards.two":"{n} כרטיסים","tl.cards.other":"{n} כרטיסים","join.h2":"הצטרפו","join.lede":"את AI-gile בונים בן אדם קטן ומספר גדול של סוכנים סבלניים. בינתיים הוא פרטי, באלפא סגורה עם חברים. רוצים לנסות כשיפתח?","join.btn":"להשאיר פרטים","join.small":"נכתוב לכם במייל, ותו לא","footer.tag":"AI-gile. בלי עוקבים, בלי עוגיות, בלי קפה של סטנד-אפ.","footer.licence":"רישיון עסקי","footer.status":"סטטוס","form.sending":"שולח…","form.failed":"זה לא הצליח: נסו שוב מאוחר יותר.","form.offline":"לא הצלחנו להגיע ל-AI-gile: נסו שוב מאוחר יותר.","interest.title":"AI-gile: תגידו לי כשהאלפא נפתחת","interest.description":"השאירו מייל כדי לשמוע מתי האלפא או הבטא הסגורה של AI-gile נפתחת.","interest.h1":"🔔 תגידו לי כשזה נפתח","interest.lede":"AI-gile בפרה-אלפא סגורה. השאירו מייל ונכתוב לכם פעם אחת, כשיהיה מקום בשבילכם.","interest.email":"המייל שלכם","interest.which":"איזה ניסוי?","interest.alpha":"אלפא סגורה: מוקדם, גולמי, הרבה שינויים","interest.beta":"בטא: יציבה יותר, אחר כך","interest.both":"כל אחד, מה שיבוא קודם","interest.submit":"תרשמו אותי לרשימה","interest.thanks":"תודה! אתם ברשימה.","interest.kept":"נשמרים רק המייל שלכם והניסוי שבחרתם, לרשימה הזו בלבד. בלי ניוזלטר, בלי עוקבים.","licence.title":"AI-gile: רישיון עסקי","licence.description":"משתמשים ב-AI-gile בעסק שלכם? בקשו רישיון עסקי חינם.","licence.h1":"📜 רישיון עסקי","licence.lede":"משתמשים ב-AI-gile בעבודה? ספרו לנו מי אתם ומה אתם עושים. אם זה עושה קצת טוב, הרישיון חינם.","licence.company":"חברה","licence.website":"אתר","licence.what":"במה אתם עוסקים","licence.how":"איך זה עוזר לעולם","licence.email":"מייל","licence.submit":"שליחת בקשה","licence.thanks":"תודה! נחזור אליכם במייל.","status.title":"הסטטוס של AI-gile","status.h1":"הסטטוס של AI-gile","status.quiet":"הכול רגוע","status.checking":"בודק…","status.offline":"אי אפשר להגיע לשירות הסטטוס כרגע (מנסה שוב)","status.updated":"עודכן {ago}","status.justNow":"ממש עכשיו","status.min":"לפני {n} דק׳","status.hours":"לפני {n} שע׳","status.days":"לפני {n} ימים"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["קנבן.","רובוטים.","האצלה."]},{"n":2,"texts":["קנבן לרובוטים.","סוכנים, מסודרים.","רעיונות, מוכנים."]},{"n":3,"texts":["קנבן בשביל רובוטים.","רעיון הופך לפיצ׳ר.","קנבן סוכנים חינם."]},{"n":5,"texts":["לוח קנבן שסוכנים מנהלים.","אתם כותבים כרטיסים. סוכנים בונים.","חינם, מקומי, נבדק, קצת משוגע."]},{"n":8,"texts":["לוח קנבן חינמי שבו סוכני AI עובדים.","כתבו רעיון. הסוכנים בונים אותו. אתם מאשרים.","אג׳ייל לבן אדם אחד ולהרבה רובוטים סבלניים."]},{"n":13,"texts":["לוח קנבן על המחשב שלכם, שבו סוכני AI לוקחים את הכרטיסים ועובדים.","כתבו רעיון. צוות סוכנים בונה אותו. בודק בודק אותו לפני שהוא מגיע אליכם.","חינם, בלי חשבונות, בלי עוקבים: לוח אחד, כמה רובוטים, ואתם בראש."]},{"n":21,"texts":["AI-gile הוא לוח קנבן לעבודה עם סוכני קוד של AI. הם לוקחים את הכרטיסים; אתם בודקים ומאשרים אותם בסוף העבודה.","לכל פרויקט יש Lead וצוות סוכני AI. כתבו תגובה על כל כרטיס, והצוות מתחיל לעבוד עליו מיד.","לוח משימות אישי וחינמי שרץ על המחשב שלכם. העובדים הם רובוטים. מי שאומר כן זה אתם, ורק אתם."]},{"n":34,"texts":["אתם מניחים רעיונות על לוח. צוות סוכני AI הופך אותם לפיצ׳רים שעובדים, בודק אותם, ומחזיר אליכם עם צעדים לנסות בעצמכם. שום דבר לא נחשב גמור עד שתגידו שהוא גמור.","AI-gile הוא לוח קנבן תוצרת בית שריץ׳ בנה בעזרה גדולה מהסוכנים שהוא מנהל היום. הוא חינמי, רץ על המחשב שלכם, ומשותף עם חברים ולא נמכר לאף אחד.","דמיינו לוח קנבן רגיל, עם עמודות מבקלוג ועד גמור, רק שאת הכרטיסים לוקחים סוכני AI. הם מדווחים על התקדמות, שואלים כשהם תקועים, ותמיד מחכים לאגודל שלכם למעלה."]},{"n":55,"texts":["AI-gile הוא לוח קנבן שהצוות בו עשוי מסוכני AI. לכל פרויקט יש Lead שמתכנן את העבודה ועוזרים שבונים אותה. כשפיצ׳ר מוכן, בודק AI מנסה אותו ומצלם מסך, ואז הוא מגיע אל הערימה שלכם. אשרו אותו, או כתבו תגובה והם יעבדו עליו מחדש, בלי שתצטרכו לחכות להם.","זה התחיל בתור דרך של אדם אחד לעקוב אחרי המון סשנים של קוד עם AI בבת אחת, והפך ללוח אמיתי. הוא רץ על המחשב שלכם, לא דורש חשבון, ואין בו עוקבים. הוא חינמי לחברים ולכל מי שסקרן. הוא גם לא גמור, אז צפו לקצוות חדים ולהפתעה קטנה פה ושם בדרך.","הנה הגרסה הכנה. עדיין אתם צריכים להמציא את הרעיונות, ועדיין אתם צריכים לבדוק את התוצאות. מה ש-AI-gile עושה זה את כל מה שביניהם: שומר על הכרטיסים בסדר, מעיר את הסוכן הנכון כשאתם מגיבים, מראה בדיוק מה השתנה, ושם הכול בערימה קצרה אחת בשבילכם, בלי דרמה ובלי רעש."]},{"n":89,"texts":["AI-gile הוא לוח קנבן חינמי שאתם מריצים על המחשב שלכם. במקום אנשים, לכל פרויקט יש צוות סוכני AI: Lead שהופך את הרעיונות שלכם לכרטיסים ולתוכנית, ועוזרים שלוקחים כרטיסים לפי עדיפות. כשמשהו נבנה, בודק AI מבצע את צעדי הבדיקה ומראה לכם מה ראה. אחר כך הוא מחכה בערימה אחת בשם ״בשבילכם״. אתם מאשרים אותו, או מגיבים והצוות מנסה שוב. הכול רץ אצלכם, בלי ענן של מישהו אחר. שום דבר לא מגיע ל״גמור״ בלעדיכם, אף פעם.","כמה דברים שאולי לא ציפיתם להם. שומר לילה ממלא את עמודת ״לביצוע״ בזמן שאתם ישנים, ובוחר כרטיסים שלא צריכים תשובה מכם. מונה טוקנים מראה כמה הסוכנים השתמשו היום והשבוע, ומצב ״בלי טוקנים״ אומר להם להפסיק להוציא. אפשר לשלוח הודעות לחברים, וההודעות הפרטיות מוצפנות מקצה לקצה. הלוח מדבר בערך 120 שפות, כולל הולנדית, פלמית, פיראטים וקלינגונית. את כל זה לא משלמים, ואף אחד גם לא מנסה למכור לכם אותו, והכול נשאר אצלכם במחשב, בשקט.","AI-gile הוא פרויקט אישי קטן, לא חברה. ריץ׳ רצה לטפל בכמה פרויקטי קוד עם AI בלי לפתוח כל אפליקציה כדי לבדוק אותם, אז הוא והסוכנים בנו לוח בשביל זה, ואחר כך השתמשו בלוח כדי לבנות את כל השאר. הוא בפרה-אלפא סגורה, כלומר הוא עובד, פחות או יותר, בשביל קומץ חברים. אין עמוד מחירים, אין ניוזלטר ואין תוכנית צמיחה. אף אחד לא ממהר לשום מקום. אם זה נשמע לכם שימושי, אפשר לבקש לנסות כשהוא ייפתח עוד קצת."]},{"n":144,"texts":["AI-gile הוא לוח קנבן לבן אדם אחד ולהרבה סוכני AI. הוא רץ על המחשב שלכם והוא חינמי לגמרי. אתם מוסיפים פרויקטים, ולכל פרויקט יש Lead וצוות קטן. מדברים עם ה-Lead, קצת כמו ב-Discord, ומתארים רעיון; ה-Lead הופך אותו לכרטיסים ולתוכנית, ואז מחכה שתלחצו על Go. הצוות עובר על הכרטיסים לפי עדיפות, בעזרת שורת פקודה פשוטה שנעשתה למודלי שפה. לפני שמשהו חוזר אליכם, בודק AI עוקב אחר הצעדים בעותק של האפליקציה ומצרף צילום מסך. עבודה גמורה מגיעה אל הערימה שלכם עם הקבצים ששונו וה-diff. אתם מאשרים, או משאירים תגובה והצוות מתעורר ומנסה שוב. בלילה הוא ממשיך לעבוד, ובבוקר אתם רואים רק את מה שדורש החלטה. כל השאר כבר מסודר מראש. רק אתם יכולים להעביר כרטיס אל ״גמור״.","יום עם AI-gile, בערך. בערב אתם משאירים כמה תגובות: הכפתור הזה במקום הלא נכון, הרשימה הזו צריכה להיות ממוינת, אפשר מצב כהה. הולכים לישון. הסוכנים קוראים את התגובות, מבצעים את השינויים, בודקים אותם ומחזירים אליכם. אם ״לביצוע״ מתרוקן, שומר הלילה ממלא אותו מהבקלוג בכרטיסים שלא צריכים תשובה מכם. בבוקר מחכה ערימה קצרה אחת: כמה שאלות וכמה דברים לנסות, לכל אחד צעדים שגם אדם מנומנם יכול לעקוב אחריהם וצילום מסך שמראה שזה עובד. עוברים על הכול בלחיצות, מאשרים את הטובים ומחזירים את השאר. מונה הטוקנים מראה כמה כל זה עלה, ומצב ״בלי טוקנים״ שם לשבועות הרזים. אין צורך להישאר ער, ואף אחד לא מצפה שתענו באמצע הלילה. אחר כך אוכלים ארוחת בוקר, ובזה הסוכנים עדיין לא יכולים לעזור.","קודם כול, מה AI-gile לא. הוא לא סטארטאפ, הוא לא למכירה, ואף אחד לא אוסף את הנתונים שלכם. זה לוח חינמי שרץ על המחשב שלכם, בלי חשבונות, בלי עוקבים ובלי עוגיות. מה שהוא כן: מקום מסודר אחד לראות את כל פרויקטי הקוד עם AI בבת אחת, עם צוות סוכנים שעושה את הכרטיסים ואתם שמחליטים. הוא ממזג כרטיסים קשורים, מתקן כותרות מבולבלות, ושם עין על כמה רזה נשאר הקוד. הוא מדבר בערך 120 שפות, מהולנדית ופלמית ועד פיראטים וקלינגונית. חברים יכולים לשלוח הודעות זה לזה, בפרטיות ובהצפנה. אותו בנו ריץ׳ ומספר גדול של סוכנים סבלניים, בעיקר תוך שימוש בו עצמו. הוא בפרה-אלפא סגורה, אז הוא גולמי במקומות. אם זה נשמע לכם כיף, בקשו יפה ואולי תיכנסו מוקדם."]}],"quips":{"1":"מילה אחת. נועז. אולי נועז מדי.","3":"שלוש מילים. כבר יותר כנות מרוב דפי המוצר.","8":"שמונה מילים. עדיין קצר מסטנד-אפ.","21":"האורכים, אגב, הם סטורי פוינטס. כמובן.","55":"חמישים וחמש מילים. שני כרטיסים הסתיימו בזמן שקראתם.","144":"זה הארוך. אין 233. הסוכנים הלכו לישון."}},"timeline":{"first-idea.name":"הרעיון הראשון","first-idea.line":"השיחה הראשונה בהחלט, לפני שהייתה אפילו שורת קוד אחת.","first-board.name":"הלוח הראשון","first-board.line":"לוח שעוקב אחרי הבנייה של עצמו: כרטיסים, עמודות, גרירה ושחרור, פרויקטים.","team-roles.name":"צוות ותפקידים","team-roles.line":"פרופילי סוכנים, תבניות צוות, מרחבים ומי עושה מה.","install.name":"התקנה וגרסאות","install.line":"קובץ zip שחבר יכול להתקין, עדכון עצמי, ערוצים וחזרה לגרסה קודמת.","usage-saver.name":"חיסכון בשימוש","usage-saver.line":"למדוד כמה עולה כל הרצה, לשמור על קוד רזה, לחסוך במכסה שלכם.","friends.name":"חברים ושיתוף","friends.line":"הודעות פרטיות, ממסר מעורבל, הזמנות, תפקידים ופרויקטים משותפים.","languages.name":"שפות","languages.line":"כל טקסט במסך בקובץ שפה, עם הולנדית ופלמית קודם.","ai-tester.name":"בודק AI","ai-tester.line":"בודק בודק קודם כל מסירה ומראה מה ראה.","website.name":"האתר","website.line":"aigile.lol, דף הטיזר וציר הזמן הזה.","streaming.name":"צ׳אט ושידור","streaming.line":"Discord, Twitch, OBS, מצב סטרימר, GIF ואימוג׳י.","no-ai.name":"מהדורה בלי AI","no-ai.line":"לוח לאנשים שכותבים קוד בלי AI, ולוחות ציבוריים.","night-watch.name":"שומר לילה","night-watch.line":"שומר ו-Scrum Master שומרים על הצוותים במשימה בזמן שאתם ישנים.","p-more.name":"כל השאר","p-more.line":"רעיונות קטנים יותר שעדיין מחכים לתור שלהם.","p-android.name":"טלפון ואנדרואיד","p-android.line":"להגיע ללוח מהטלפון, ואחר כך אפליקציית אנדרואיד מקורית.","p-release.name":"אלפא ומעבר לה","p-release.line":"אלפא סגורה, האתר החי, ואז בטא.","p-languages.name":"עוד שפות","p-languages.line":"יותר ממאה שפות, ומצב צלילה למי שלומד.","p-engines.name":"עוד מנועי AI","p-engines.line":"לבחור Claude, Codex או Gemini לכל סוכן.","p-pro.name":"עבודה מקצועית","p-pro.line":"תוויות סיכון, שערי מיזוג, כרטיסי תקלה ומעקות בטיחות.","p-self.name":"דואגים לכם","p-self.line":"מצב עייפות, תזכורות לטפל בעצמכם ו-4:20.","p-servers.name":"שרתים וקנה מידה","p-servers.line":"הגדרות שרת גלובליות, תפקידים ותכנון לצמיחה.","p-livestream.name":"תוספות שידור","p-livestream.line":"צ׳אט של Twitch, אימוג׳י מותאמים ותצוגה חיה ציבורית."}};
